package com.hbm.client.wiaj.actors;
import com.hbm.client.gui.font.LegacyFonts;import java.util.*;import net.minecraft.client.gui.GuiGraphics;import net.minecraft.world.item.ItemStack;
public final class JarStackText {
 public static void draw(GuiGraphics graphics,List<Object[]> lines,int x,int y,int width,int height){if(lines.isEmpty())return;var font=LegacyFonts.get();int textHeight=0,longest=0;for(var line:lines){int length=0;boolean stacks=false;for(Object value:line){if(value instanceof String text)length+=font.width(text);else{length+=18;stacks=true;}}textHeight+=stacks?18:10;longest=Math.max(longest,length);}int minX=x+12,minY=y-12;if(minX+longest>width)minX-=28+longest;if(minY+textHeight+6>height)minY=height-textHeight-6;graphics.pose().pushPose();graphics.pose().translate(0,0,300);int bg=0xf0100010,first=0x505000ff,second=(first&0xfefefe)>>1|first&0xff000000;graphics.fill(minX-3,minY-4,minX+longest+3,minY+textHeight+4,bg);graphics.fill(minX-4,minY-3,minX-3,minY+textHeight+3,bg);graphics.fill(minX+longest+3,minY-3,minX+longest+4,minY+textHeight+3,bg);graphics.fillGradient(minX-3,minY-2,minX-2,minY+textHeight+2,first,second);graphics.fillGradient(minX+longest+2,minY-2,minX+longest+3,minY+textHeight+2,first,second);graphics.fill(minX-3,minY-3,minX+longest+3,minY-2,first);graphics.fill(minX-3,minY+textHeight+2,minX+longest+3,minY+textHeight+3,second);for(int index=0;index<lines.size();index++){var line=lines.get(index);boolean stacks=Arrays.stream(line).anyMatch(value->!(value instanceof String));int indent=0;for(Object value:line){if(value instanceof String text){graphics.drawString(font,text,minX+indent,minY+(stacks?4:0),-1,true);indent+=font.width(text)+2;}else{var stack=(ItemStack)value;graphics.renderItem(stack,minX+indent,minY);graphics.renderItemDecorations(font,stack,minX+indent,minY);indent+=18;}}if(index==0)minY+=2;minY+=stacks?18:10;}graphics.pose().popPose();}
 private JarStackText(){}
}
